//! Traditional-to-simplified Chinese character table.
//!
//! Generated from OpenCC `data/dictionary/TSCharacters.txt` (BYVoid/OpenCC,
//! Apache License 2.0): the first simplified candidate of every
//! traditional character, sorted by code point for binary search. Used by
//! the `t2s` tokenizer option, index and query alike, so a character-level
//! conversion is all that matching needs (no phrase table).

/// Simplified form of a traditional character, if the table has one.
pub(super) fn to_simplified(c: char) -> Option<char> {
    TABLE
        .binary_search_by_key(&c, |(traditional, _)| *traditional)
        .ok()
        .map(|index| TABLE[index].1)
}

