#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_sorted_and_converts_common_characters() {
        assert!(TABLE.windows(2).all(|w| w[0].0 < w[1].0));
        assert_eq!(to_simplified('電'), Some('电'));
        assert_eq!(to_simplified('腦'), Some('脑'));
        assert_eq!(to_simplified('網'), Some('网'));
        assert_eq!(to_simplified('电'), None);
        assert_eq!(to_simplified('a'), None);
    }
}
